<?php $labelMax=max([1,...array_map(static fn($r)=>(int)$r['total'],$labels)]);$colorMax=max([1,...array_map(static fn($r)=>(int)$r['total'],$colors)]);$styleMax=max([1,...array_map(static fn($r)=>(int)$r['total'],$styles)]);$wearMax=max([1,...array_map(static fn($r)=>(int)$r['wears'],$wears)]);$statusLabels=['available'=>'Disponible','laundry'=>'Au lavage','repair'=>'A reparer','unavailable'=>'Indisponible','archived'=>'Archive'];$monthlyMax=[];foreach($spendTrend as $r)$monthlyMax[$r['currency']]=max($monthlyMax[$r['currency']]??0,(float)$r['total']); ?>
<section class="page-heading"><div><p class="eyebrow">VOTRE GARDE-ROBE, EN CHIFFRES REELS</p><h1>Statistiques</h1><p class="subheading">Les montants restent separes par devise. Aucun chiffre n'est simule.</p></div></section>
<section class="stat-grid"><?php foreach($labels as $row): ?><article class="stat-card"><span class="stat-number"><?= e($row['total']) ?></span><span class="stat-title"><?= e($row['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$row['total']/$labelMax*100) ?>%"></i></div></article><?php endforeach; ?><article class="stat-card"><span class="stat-number"><?= e(array_sum(array_column($labels,'total'))) ?></span><span class="stat-title">Vetements (archives comprises)</span></article><article class="stat-card"><span class="stat-number"><?= e($outfitCount) ?></span><span class="stat-title">Tenues sauvegardees</span></article></section>
<div class="analytics-grid"><article class="analytics-panel"><p class="eyebrow">ETAT DES PIECES</p><h2>Disponibilite</h2><?php foreach($statusLabels as $key=>$label): ?><div class="metric-row"><span><?= e($label) ?></span><b><?= e($statuses[$key]??0) ?></b></div><?php endforeach; ?></article><article class="analytics-panel"><p class="eyebrow">COULEURS</p><h2>Repartition</h2><?php foreach($colors as $row): ?><div class="bar-row"><span><?= e($row['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$row['total']/$colorMax*100) ?>%"></i></div><b><?= e($row['total']) ?></b></div><?php endforeach; ?></article><article class="analytics-panel"><p class="eyebrow">STYLES</p><h2>Dans votre catalogue</h2><?php foreach($styles as $row): ?><div class="bar-row"><span><?= e($row['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$row['total']/$styleMax*100) ?>%"></i></div><b><?= e($row['total']) ?></b></div><?php endforeach; ?></article><article class="analytics-panel"><p class="eyebrow">FREQUENCE D'USAGE</p><h2>Pieces les plus portees</h2><?php foreach($wears as $row): ?><div class="bar-row"><span><?= e($row['name']) ?></span><div class="bar-track"><i style="width:<?= round((int)$row['wears']/$wearMax*100) ?>%"></i></div><b><?= e($row['wears']) ?></b></div><?php endforeach; ?></article><article class="analytics-panel"><p class="eyebrow">DEPENSES CETTE ANNEE</p><h2>Par devise</h2><?php if(!$spend): ?><p class="subheading">Aucun achat enregistre cette annee.</p><?php else: foreach($spend as $row): ?><div class="metric-row"><span><?= e($row['currency']) ?></span><b><?= e(number_format((float)$row['total'],2,',',' ')) ?></b></div><?php endforeach;endif; ?></article><article class="analytics-panel"><p class="eyebrow">EVOLUTION DES DEPENSES</p><h2>12 derniers mois</h2><?php if(!$spendTrend): ?><p class="subheading">Aucune depense sur cette periode.</p><?php else: foreach($spendTrend as $row): ?><div class="bar-row"><span><?= e(date('m/Y',strtotime($row['month'].'-01'))) ?> · <?= e($row['currency']) ?></span><div class="bar-track"><i style="width:<?= round((float)$row['total']/$monthlyMax[$row['currency']]*100) ?>%"></i></div><b><?= e(number_format((float)$row['total'],0,',',' ')) ?></b></div><?php endforeach;endif; ?></article></div>